// ── HEXAGONAL ARCHITECTURE ────────────────────────────────────
// Step 1: Domain defines outbound ports as plain interfaces (JS duck-typing)

// Outbound port: what the domain needs from storage
// { save(order): void, findById(id): Order|null }

// Outbound port: what the domain needs for notifications
// { send(to, subject, body): void }

// Step 2: Domain logic — zero imports from infrastructure
function createOrderService(orderRepo, emailSender) {
  return {
    placeOrder(customerId, items) {
      if (!items.length) throw new Error('Order must have at least one item');
      const total = items.reduce((sum, item) => sum + item.price * item.qty, 0);
      const order = { id: `ord-${Date.now()}`, customerId, items, total, status: 'placed' };
      orderRepo.save(order);          // calls outbound port
      emailSender.send(             // calls outbound port
        customerId,
        'Order confirmed',
        `Your order total is $${total}`
      );
      return order;
    },
    getOrder(id) {
      const order = orderRepo.findById(id);
      if (!order) throw new Error(`Order ${id} not found`);
      return order;
    }
  };
}

// Step 3: In-memory adapters for testing — no database needed
const inMemoryOrderRepo = {
  _store: {},
  save(order)       { this._store[order.id] = order; },
  findById(id)      { return this._store[id] || null; }
};
const spyEmailSender = {
  sent: [],
  send(to, subject, body) { this.sent.push({ to, subject, body }); }
};

// Step 4: Run domain logic — no DB, no HTTP, no mocking framework
const svc = createOrderService(inMemoryOrderRepo, spyEmailSender);
const order = svc.placeOrder('cust-42', [{ price: 49, qty: 2 }, { price: 9, qty: 1 }]);
console.log('Total:', order.total);          // 107
console.log('Status:', order.status);        // 'placed'
console.log('Emails sent:', spyEmailSender.sent.length); // 1

const fetched = svc.getOrder(order.id);
console.log('Retrieved:', fetched.id === order.id); // true

