// ── BOUNDED CONTEXTS: different models for same real-world entity ──

// Catalogue Context — what the product team cares about
function CatalogueProduct(id, name, description, photos, categoryId) {
  return { id, name, description, photos, categoryId };
}

// Inventory Context — what the warehouse team cares about
function InventoryItem(id, sku, warehouseLocation, stockLevel, reorderPoint) {
  return { id, sku, warehouseLocation, stockLevel, reorderPoint,
    isLowStock() { return this.stockLevel <= this.reorderPoint; }
  };
}

// Billing Context — what the accounting team cares about
function BillingLineItem(productId, unitPrice, taxCategory, discountRules) {
  return {
    productId, unitPrice, taxCategory, discountRules,
    calculateTotal(qty, customerTier) {
      const discount = this.discountRules[customerTier] || 0;
      return this.unitPrice * qty * (1 - discount);
    }
  };
}

// Anti-Corruption Layer: translates Catalogue product into Billing terms
// when an order is placed
function billingLineItemFromCatalogueProduct(catalogProduct, priceList, taxConfig) {
  const priceEntry = priceList[catalogProduct.id];
  if (!priceEntry) throw new Error(`No price defined for product ${catalogProduct.id}`);
  return BillingLineItem(
    catalogProduct.id,
    priceEntry.unitPrice,
    taxConfig[catalogProduct.categoryId] || 'STANDARD',
    priceEntry.discountRules || {}
  );
}

// Demonstration
const widget = CatalogueProduct('p1', 'Widget Pro', 'A great widget', [], 'tools');
const priceList = { p1: { unitPrice: 49.99, discountRules: { vip: 0.15, standard: 0 } } };
const taxConfig = { tools: 'REDUCED_RATE' };

const billingItem = billingLineItemFromCatalogueProduct(widget, priceList, taxConfig);
console.log('Tax category:', billingItem.taxCategory);          // 'REDUCED_RATE'
console.log('VIP total for 3:', billingItem.calculateTotal(3, 'vip')); // ~127.47

// The Catalogue context knows NOTHING about prices or taxes
// The Billing context knows NOTHING about photos or descriptions
// Each can evolve independently — this is the power of bounded contexts

// ── EVENT-DRIVEN ARCHITECTURE ─────────────────────────────────

// In-process event bus (same pattern as a real broker, just synchronous)
const EventBus = {
  _handlers: {},
  on(eventName, handler) {
    if (!this._handlers[eventName]) this._handlers[eventName] = [];
    this._handlers[eventName].push(handler);
  },
  emit(eventName, payload) {
    const handlers = this._handlers[eventName] || [];
    // In a real broker: this is where async delivery + retry happens
    handlers.forEach(handler => {
      try {
        handler(payload);
      } catch (err) {
        console.error(`[Bus] Handler failed for ${eventName}:`, err.message);
        // Real broker: dead-letter queue, retry with backoff
      }
    });
  }
};

// ── PRODUCER — knows nothing about who consumes ───────────────
function OrderService(eventBus) {
  return {
    placeOrder(customerId, items) {
      const order = {
        id: `ord-${Date.now()}`,
        customerId,
        items,
        total: items.reduce((s, i) => s + i.price * i.qty, 0),
        placedAt: new Date().toISOString()
      };
      // Domain logic here... then publish
      eventBus.emit('OrderPlaced', order);
      return order;
    }
  };
}

// ── CONSUMER 1: Inventory — independent ───────────────────────
EventBus.on('OrderPlaced', (order) => {
  console.log(`[Inventory] Reserving stock for order ${order.id}:`);
  order.items.forEach(item =>
    console.log(`  - ${item.qty}x product ${item.productId}`)
  );
});

// ── CONSUMER 2: Email — independent ───────────────────────────
EventBus.on('OrderPlaced', (order) => {
  console.log(`[Email] Sending confirmation to customer ${order.customerId}`);
  console.log(`  Subject: Order ${order.id} confirmed — total $${order.total}`);
});

// ── CONSUMER 3: Analytics — independent ───────────────────────
EventBus.on('OrderPlaced', (order) => {
  console.log(`[Analytics] Logging conversion: order=${order.id} value=${order.total}`);
});

// ── DEMO ───────────────────────────────────────────────────────
const orderSvc = OrderService(EventBus);
orderSvc.placeOrder('cust-7', [
  { productId: 'p1', price: 29.99, qty: 2 },
  { productId: 'p2', price: 9.99, qty: 1 }
]);

// Adding a new consumer (e.g., FraudDetection) requires ZERO changes
// to OrderService or any other consumer:
